import React, { useState } from 'react';
import { SplitButton } from 'primereact/splitbutton';

export default function Accessibility() {
    const [value, setValue] = useState('');
    
    return (
        <div>
            <label htmlFor="splitButton-accessibility">Accessible SplitButton</label>
            <SplitButton 
                id="splitButton-accessibility"
                value={value} 
                onChange={(e) => setValue(e.target.value)}
                aria-label="Accessible SplitButton input"
                placeholder="Enter splitButton"
            />
        </div>
    );
}